#!/usr/bin/env python3
"""PCUA_for_p3.py: build PCUA_FOR_P3.json from PCUA_EQ_STATUS.json plus the classified semantic / interface differences.
Analytical statements below are derived from the normalized diffs (PCUA_JOB_STATUS.json) and marked ANALYTICAL: not machine checked here."""
import json
from pathlib import Path
H=Path(__file__).resolve().parent
E=json.loads((H/'PCUA_EQ_STATUS.json').read_text())['modules']
obl=[]
for M,rows in E.items():
    for r in rows:
        s=r['status']
        if s.startswith('PROVED') or s.startswith('REUSED_FROM_P0') :continue
        o=dict(gate_module=M,definition=r['gate_definition'],status=s,rust=r['rust'])
        for k in ('statement','error_class','first_failing_goal_or_error','first_failing_fresh_declaration','blocked_by','job','fresh_emission','reason','fresh_candidates'):
            if r.get(k):o[k]=r[k]
        if r.get('normalized_text_diff_gate_to_fresh'):o['normalized_text_diff_gate_to_fresh']=r['normalized_text_diff_gate_to_fresh']
        obl.append(o)
sem=[
 dict(id='SEM-1',class_='CHECKED_VS_WRAPPING_ARITHMETIC',description='The gate bodies use Aeneas checked arithmetic (`+ - *` and `>>>` in Result, fail on overflow/underflow or oversize shift); the fresh frozen emission translates the same Rust with `Std.<ty>.wrapping_*` lifted into Result (the frozen release profile has no overflow checks). Both are exact translations of different arithmetic semantics; the bodies are equal exactly on inputs where no checked operation fails.',
  instances=[
   dict(definition='AspisR1CurrentWide.field.M31.add',statement='fresh frozen NFG_InverseRef (NMH_E008) vs gate CW_Funs_sources',disagree_when='ANALYTICAL: self + rhs >= 2^32 in U32 (gate: fail; fresh: wraps then subtracts P when >= P). Witness: self = rhs = 4294967295#u32. Equal for self, rhs < P = 2147483647 (no checked op can fail: self+rhs < 2^32, `s - P` is guarded by s >= P).'),
   dict(definition='AspisR1CurrentWide.field.M31.sub',disagree_when='ANALYTICAL: self + P >= 2^32, i.e. self >= 2147483649, or rhs > self + P (U32 underflow). Witness: self = 4294967295, rhs = 0 (gate fails at self + P). Equal for self, rhs < P (the `s - P` is guarded by s >= P).'),
   dict(definition='AspisR1CurrentWide.field.M31.mul',disagree_when='ANALYTICAL: never. Both U32 factors are cast to U64, so the U64 product is at most (2^32-1)^2 < 2^64: no overflow, so gate and fresh agree on all inputs. The equality needs a no-overflow lemma (not provable by rfl/unfold, which is why the generated stage 2 failed).'),
   dict(definition='AspisR1CurrentWide.field.reduce_u64',disagree_when='ANALYTICAL: never. i1 = x & P <= P, i2 = x >> 31 < 2^33, so x1 < 2^34; the second round sums stay below 2^32 + 2^31; `x3 - P` is guarded by x3 >= P. All checked ops succeed for every U64 x; the equality needs this bound lemma.'),
   dict(definition='AspisR1CurrentWide.field.M31.reduce_u64, M31.double, CM31.add, CM31.sub, CM31.mul, field.mul_by_r',disagree_when='ANALYTICAL: inherit the conditions of M31.add / M31.sub (callees) and, for CM31.mul, the U64 sums of products of M31 values: with canonical (< P) arguments no checked operation fails.'),
   dict(definition='AspisR1.FIp_NativeDots.fast_dots.four_dots_one* (gate RPz7_FIp_NativeDots)',disagree_when='ANALYTICAL: the index arithmetic `slot * 120`, `term * 4`, `i + i1` and `+ 4` on Usize is checked in the gate and wrapping in the fresh emission: they differ when slot * 120 + term * 4 + 4 overflows 2^64 (gate: fail). Equal when no index expression overflows (slot * 120 + term * 4 + 4 < 2^64 for every term reached by the loop).'),
   dict(definition='transport.Variant.row_loop.body (gate RPz7_FIo_NativeFuns)',disagree_when='ANALYTICAL: gate uses `j >>> i` and `i2 <<< i4` (checked shifts: fail when the shift amount >= 64); fresh uses wrapping_shr / wrapping_shl (shift amount reduced mod 64). Equal when i, i4 < 64.')],
  p3_task='Prove, per definition, equality of the gate and fresh bodies under the stated domain (or the all-inputs no-overflow lemma for M31.mul and reduce_u64), then discharge the domain at the call sites (canonical field elements) as part of the consuming bridge. Do not hide the domain: a theorem that holds only on the domain is not the equality of the two constants.'),
 dict(id='LIB-1',class_='AENEAS_LIBRARY_API_MISMATCH',description='Fresh frozen emissions pass the shift amount of wrapping_shr/wrapping_shl at the Rust operand type (31#i32 for U64.wrapping_shr in fast_dots; a Usize in transport row_loop), but the gate Lean environment declares these functions with a U32 amount. The fresh declarations therefore do not elaborate against the gate library ("Application type mismatch ... expected U32").',
  instances=[dict(definition='RPz7_FIp_NativeDots.fast_dots.four_dots_one_loop0.body',error='31#i32 : IScalar I32, expected U32 in i2.wrapping_shr 31#i32'),dict(definition='RPz7_FIo_NativeFuns.transport.Variant.row_loop.body',error='i : Usize, expected U32 in j.wrapping_shr i'),dict(definition='fresh-only (dropped, not gate-reached) verifier.* functions of PCQ_E415',error='same message at line 250 of the D1 bundle')],
  p3_task='Either re-emit/compile the fresh frozen text against the Aeneas library version that matches the emitter (a toolchain-pairing question, not decided here; no trust row proposed), or state the equality through a thin shim lemma between the two library signatures. Until then these fresh declarations cannot be compared to the gate in the gate environment.'),
 dict(id='NAME-1',class_='GATE_MODULE_SPLIT_NAME_MISMATCH',description='The gate RPz7_FIp_NativeDots refers to field decoders as AspisR1.FIp_DotDecode.field.{M31,QM31}.from_le_bytes (module DotDecode), while the fresh emission names them aspis_core.field.M31.from_le_bytes in the same namespace as the caller. With `open FIo_Native` the fresh name resolves to FIo_Native.aspis_core.field.M31.from_le_bytes, which does not exist in the gate ("Unknown constant").',
  p3_task='Provide the alias lemma fresh callee = DotDecode gate callee. PCUA proved the DotDecode side (PRVEq_DotDecode: PRVFresh.field.{P,M31,CM31,QM31}.from_le_bytes = gate, fresh text from NMH_E013, which is text-identical to the corresponding Q415 declarations only if checked by P3), so the alias reduces to the text identity of the NMH_E013 and PCQ_E415 declarations.'),
 dict(id='NAME-2',class_='FRESH_CRATE_PREFIX_MISMATCH',description='NMH_E008/E024 (NFG_InverseRef, crate aspis-core) name the items field.mul_by_r / field.reduce_u64, the gate RPz7_FIo_NativeFuns names them aspis_core.field.mul_by_r / aspis_core.field.reduce_u64 (cost-probe crate view). The generator pairs by exact name and found 0 common declarations.',p3_task='Re-emit the two items from the cost-probe crate root (P1a/P1b follow-up) or add a recorded prefix-rename step to the generator; then run stage 1/2.'),
 dict(id='STRUCT-1',class_='GENERATOR_STRUCTURE_EQUIV_FAILURE',description='verifier.Reader (Stage2ContinuationTypes, fresh NHR_tx2_common): the generated Equiv fails with "Fields missing: `at`" (a field named `at`, a Lean keyword-like name, in the structure literal).',p3_task='Hand or generator-assisted Equiv for verifier.Reader; no semantic issue observed.'),
 dict(id='TYPES-1',class_='INDUCTIVE_OR_COMPLEX_STRUCTURE_TEXT_ONLY',description='Inductives and structures with non-simple fields get no Lean theorem from the generator (P0 limitation). Their entries are TEXT_IDENTICAL_ONLY in PCUA_EQ_STATUS.json and count as not proved.',p3_task='Generate Equiv / inductive-iso proofs (cases-based) for verifier.Error, transport.Variant, verifier.Phase, multiproof.Arity, verifier.Prepared, verifier.BatchedWeights, verifier.Accumulator, verifier.QueryGeometry, verifier.View, aspis_core.r0.Error, weights.Weights, weights.Weights.scalar_factor.closure.'),
 dict(id='EXT-1',class_='EXTERNAL_BOUNDARY_RESOLVED_BY_NAME',description='Theorems whose fresh declaration reaches a fresh External-template name resolve it to the gate constant of the same name (see PCUA_HAND_MODELS.json and conditional_on_external_boundaries in PCUA_EQ_STATUS.json). These theorems are conditional on that boundary; the dependent definitions are listed there (fast_pairing.EbyKDot.push reaches the opaque Dot.push; EbyKDot.finish reaches WideExact.from_limbs; Q.from_wide reaches WideExact.to_limbs; DotDecode CM31/QM31.from_le_bytes reach core::option Try::branch/from_residual).',p3_task='Prove or accept each boundary explicitly; PCUA proposes no trust row.'),
 dict(id='PARSE-1',class_='GENERATOR_GATE_PARSE_LIMIT',description='RPz7_FIp_NativeDots.fast_dots.four_dots_one_loop0_loop0.body is the first declaration after the `namespace` line with no blank line; the generator splits blocks on blank lines and reads it as header text, so it is not paired (the other five NativeDots definitions are paired and fail for NAME-1/LIB-1/SEM-1).',p3_task='Fix block splitting for a declaration directly after a namespace line.'),
]
(H/'PCUA_FOR_P3.json').write_text(json.dumps(dict(schema='PCUA_FOR_P3/1',target_established=False,
 note='Obligations (every definition of the hub cluster that is not PROVED_* and not reused from P0) and the classified semantic/interface differences. Analytical domain statements are derived from the normalized diffs; no domain restriction is proved here.',
 semantic_and_interface_differences=sem,obligations=obl),indent=1))
print(len(obl),'obligations')
